def handle_users_by_ids(params: dict) -> tuple[int, dict]:
    ids = params.get("ids")
    if not isinstance(ids, list) or not 1 <= len(ids) <= 20:
        return 400, {"error": "invalid ids"}
    if not all(isinstance(raw, str) and raw.isdigit() for raw in ids):
        return 400, {"error": "invalid ids"}
    return 200, {"users": users.get_users([int(raw) for raw in ids])}
